import {calcEscape as esc,calcMoney,calcParentLabel} from './calculator-view.js';
import {calendarDate,periodText} from './polish.js';
import {todayString} from './age.js';
import {cleanName} from './profile.js';
export function calcDownload(name,content,type='text/html;charset=utf-8'){
  const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);
}
export function calcDocumentPage(title,body,{simulation=false}={}){return `<!doctype html><html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(title)}</title><style>body{font:17px/1.7 system-ui;color:#244435;max-width:980px;margin:auto;padding:36px}h1,h2{color:#236d4d}table{border-collapse:collapse;width:100%}th,td{padding:12px;border-bottom:1px solid #d6e7dc;text-align:left}.notice{padding:18px;background:#edf7f1;border:2px solid #8db59e;border-radius:14px}small{font-size:14px}a{color:#236d4d}@media print{button{display:none}.notice{border:2px solid #236d4d}}</style><h1>${esc(title)}</h1>${simulation?'<p class="notice"><strong>Symulacja · dokument przykładowy</strong></p>':''}${body}<p><small>Przewodnik Przyszłego Rodzica · ${calendarDate(todayString())}</small></p><button onclick="print()">Drukuj / zapisz jako PDF</button></html>`;}
export function calculatorExport(result){
  const body=`<p>Scenariusz na podstawie danych użytkownika; nie jest decyzją ani potwierdzeniem prawa do świadczenia.</p><p>Zasady ${esc(result.rulesVersion)} · ${calendarDate(result.reviewedAt)}</p>${result.formalDecision?`<h2>${esc(result.formalDecision.label)}</h2><ul>${result.formalDecision.issues.map(i=>'<li>'+esc(i.message)+'</li>').join('')}</ul><h3>Dalsze kroki</h3><ol>${result.formalDecision.nextSteps.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><h3>Dokumenty do indywidualnego ustalenia</h3><ul>${result.formalDecision.documents.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul>`:''}${result.audit?'<details><summary>Odtworzenie danych i wersji obliczenia</summary><pre>'+esc(JSON.stringify({audit:result.audit,input:result.input,formalDecision:result.formalDecision},null,2))+'</pre></details>':''}${result.warnings.map(w=>`<p class="notice">${esc(w)}</p>`).join('')}<table><tr><th>Okres</th><th>Rodzic</th><th>Daty</th><th>Kwota brutto</th></tr>${result.periods.map(p=>`<tr><td>${esc(p.title)}</td><td>${esc(calcParentLabel(result.input,p.parent))}</td><td>${esc(periodText(p,{long:true}))}</td><td>${calcMoney(p.gross)}</td></tr>`).join('')}</table><h2>Terminy</h2>${result.deadlines.map(d=>`<p><strong>${calendarDate(d.start)}</strong> — ${esc(d.title)}<br>${esc(d.description||'')}</p>`).join('')}<h2>Dokumenty</h2>${result.documents.map(d=>`<h3>${esc(calcParentLabel(result.input,d.parent))}</h3><p>${esc(d.recipient)}</p><ul>${d.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}<h2>Źródła</h2>${result.sources.map(s=>`<p><a href="${esc(s.url)}">${esc(s.name)}</a></p>`).join('')}`;
  return calcDocumentPage(result.caseTitle||result.title,body);
}
export function createCalculatorTools({sheetContent,notify,getInput,getResult,getProfile,onImport}){
  async function simulate(operation,extra={}){const r=await fetch('/api/calculator/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation,...extra})}),data=await r.json();if(!r.ok)throw new Error(data.error||'Nie udało się otworzyć symulacji.');return data;}
  function show(title,body){sheetContent(title,body);}
  const notice='';
  function error(e){notify(e.message||'Nie udało się wykonać symulacji.');}
  function open(){
    show('Dokumenty i połączenia',`${notice}<div class="calc-tools-grid"><button class="secondary" data-tool="login">mObywatel — symulacja</button><button class="secondary" data-tool="insurance">ZUS — przykładowe ubezpieczenie</button><button class="secondary" data-tool="debt">Zaświadczenie o zadłużeniu — symulacja</button><button class="secondary" data-tool="ezla">e-ZLA — przykładowy podgląd</button><button class="secondary" data-tool="ezus">eZUS — przygotuj zapytanie</button><button class="secondary" data-tool="application">Wnioski o urlopy i świadczenia</button><button class="secondary" data-tool="usc">Odpis aktu urodzenia — symulacja</button></div><div class="calc-links"><a href="https://www.zus.pl/ezus/logowanie?jezyk=pl" target="_blank" rel="noopener noreferrer">Otwórz portal eZUS</a><a href="https://www.gov.pl/web/cyfryzacja/rejestr-stanu-cywilnego" target="_blank" rel="noopener noreferrer">Oficjalne informacje o rejestrze USC</a></div>`);
    document.querySelectorAll('[data-tool]').forEach(button=>button.addEventListener('click',()=>tool(button.dataset.tool)));
  }
  async function tool(kind){try{
    if(kind==='login'){const data=await simulate('login');show('mObywatel — symulacja',`<dl class="case-facts"><div><dt>Imię i nazwisko</dt><dd>${esc(data.identity.name)}</dd></div><div><dt>Data urodzenia</dt><dd>${calendarDate(data.identity.birthDate)}</dd></div></dl><button class="primary" id="demo-identity-use">Użyj daty urodzenia w kalkulatorze</button><button class="secondary" id="demo-insurance-next">Sprawdź dane ubezpieczenia</button>`);document.querySelector('#demo-identity-use').onclick=()=>{onImport({importFields:[{field:'birthDate',value:data.identity.birthDate}],parent:getProfile()?.parentRole==='father'?1:0,title:0,demo:true});document.querySelector('#sheet').close();};document.querySelector('#demo-insurance-next').onclick=()=>tool('insurance');}
    if(kind==='insurance'){
      show('Przykładowe dane ZUS',`${notice}<label class="field-label" for="demo-variant">Zestaw do przetestowania</label><select id="demo-variant"><option value="employee">Dwoje ubezpieczonych pracowników</option><option value="business-debt">Działalność z przykładowym zadłużeniem</option><option value="uninsured">Brak tytułu chorobowego u pierwszego rodzica</option></select><button class="primary" id="demo-import">Wstaw przykładowe dane do kalkulatora</button>`);
      document.querySelector('#demo-import').onclick=async()=>{try{const data=await simulate('insurance',{variant:document.querySelector('#demo-variant').value});onImport({parents:data.parents,dataOrigin:'demo'});document.querySelector('#sheet').close();notify('Wstawiono dane przykładowe. Możesz je zmienić.');}catch(e){error(e);}};
    }
    if(kind==='ezla'){
      const pregnancy=getProfile()?.caseStage==='pregnancy';
      show('e-ZLA — symulacja',`<label class="field-label" for="demo-ezla-variant">Rodzaj przykładowego dokumentu</label><select id="demo-ezla-variant"><option value="pregnancy" ${pregnancy?'selected':''}>Niezdolność do pracy w ciąży — kod B</option><option value="own-illness" ${!pregnancy?'selected':''}>Choroba własna — bez kodu B</option><option value="child-care">Opieka nad chorym dzieckiem</option></select><button class="primary" id="demo-ezla-preview">Pokaż dokument</button>`);
      document.querySelector('#demo-ezla-preview').onclick=async()=>{try{const data=await simulate('ezla',{variant:document.querySelector('#demo-ezla-variant').value}),c=data.certificates[0],care=data.variant==='child-care',parent=care?(getInput().care?.parent||0):0;show('e-ZLA — symulacja',`<dl class="case-facts"><div><dt>Osoba ubezpieczona</dt><dd>${esc(calcParentLabel(getInput(),parent))}</dd></div><div><dt>Powód</dt><dd>${esc(c.reason)}</dd></div><div><dt>Okres</dt><dd>${periodText(c)}</dd></div>${c.code?'<div><dt>Kod</dt><dd>'+esc(c.code)+'</dd></div>':''}${care?'<div><dt>Urodzenie dziecka — przykład</dt><dd>'+calendarDate(data.childBirthDate)+'</dd></div>':''}</dl><button class="primary" id="demo-ezla-use">Zastosuj w ${care?'opiece':'chorobowym'}</button>`);document.querySelector('#demo-ezla-use').onclick=()=>{const old=getInput(),patch=care?{focus:'care',childBirthDate:old.childBirthDate||data.childBirthDate,care:{...old.care,parent,start:c.start,days:c.days,type:'sick-child'},formalCase:{...old.formalCase,careCertificate:'yes'}}:{focus:'sickness',sickness:{...old.sickness,start:c.start,days:c.days,certificate:'yes',pregnant:data.variant==='pregnancy'}};onImport({...patch,eventDate:c.start,dateKind:'actual',dataOrigin:'demo'});document.querySelector('#sheet').close();};}catch(e){error(e);}};
    }
    if(kind==='debt'){
      show('Zaświadczenie o zadłużeniu — symulacja',`<p>Przykład działalności gospodarczej z zaległościami, które mają znaczenie przy sprawdzaniu prawa do zasiłku.</p><div class="calc-fields"><label class="calc-field"><span>Stan należności na dzień</span><input id="demo-debt-date" type="date" value="${getInput().eventDate||todayString()}"></label><label class="calc-field"><span>Zadłużenie w składkach społecznych (zł)</span><input id="demo-debt" type="number" min="0" step=".01" value="${getInput().parents[0].debt||1450.75}"></label></div><button class="primary" id="demo-debt-create">Pokaż zaświadczenie</button>`);
      document.querySelector('#demo-debt-create').onclick=async()=>{try{const data=await simulate('debt',{debt:document.querySelector('#demo-debt').value,asOf:document.querySelector('#demo-debt-date').value||todayString()}),body=`<p>Stan należności na <strong>${calendarDate(data.asOf)}</strong></p><table class="simulation-table"><thead><tr><th>Rodzaj należności</th><th>Kwota</th></tr></thead><tbody>${data.rows.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+calcMoney(r.amount)+'</td></tr>').join('')}<tr><th>Razem</th><th>${calcMoney(data.totalDebt)}</th></tr></tbody></table><p>${esc(data.message)}</p>`;show('Zaświadczenie o zadłużeniu — symulacja',body+`<div class="calc-fields"><label class="calc-field"><span>Osoba w kalkulatorze</span><select id="demo-debt-parent">${[0,1].map(p=>'<option value="'+p+'">'+esc(calcParentLabel(getInput(),p))+'</option>').join('')}</select></label><label class="calc-field"><span>Tytuł ubezpieczenia tej osoby</span><select id="demo-debt-title"><option value="0">Główny tytuł</option><option value="1">Dodatkowy tytuł 1</option><option value="2">Dodatkowy tytuł 2</option><option value="3">Dodatkowy tytuł 3</option></select></label></div><label class="calc-field"><span>Co zastosować w kalkulatorze?</span><select id="demo-debt-import"><option value="balance" ${getInput().parents[0].occupation==='business'?'selected':''}>Tylko saldo istniejącej działalności</option><option value="business" ${getInput().parents[0].occupation!=='business'?'selected':''}>Saldo i osobny przykład ubezpieczenia JDG</option></select></label><button class="primary" id="demo-debt-use">Zastosuj wybrany zestaw</button><button class="secondary" id="demo-debt-download">Pobierz zaświadczenie — symulacja</button>`);document.querySelector('#demo-debt-download').onclick=()=>calcDownload('przykladowe-zadluzenie.html',calcDocumentPage('Zaświadczenie o zadłużeniu — symulacja',body,{simulation:true}));document.querySelector('#demo-debt-use').onclick=async()=>{try{const parent=Number(document.querySelector('#demo-debt-parent').value),title=Number(document.querySelector('#demo-debt-title').value),target=title?getInput().parents[parent].extraTitles?.[title-1]:getInput().parents[parent],fields=[{field:'debt',value:data.socialDebt}];if(document.querySelector('#demo-debt-import').value==='business'){const sample=await simulate('insurance',{variant:'business-debt'}),business=sample.parents[0];for(const key of ['occupation','coverage','insuranceFrom','basis'])fields.push({field:key,value:business[key]});}else if(target?.occupation!=='business'){notify('Wybierz tytuł działalności albo zestaw z przykładowym ubezpieczeniem JDG.');return;}onImport({importFields:fields,parent,title,demo:true});document.querySelector('#sheet').close();}catch(e){error(e);}};}catch(e){error(e);}};
    }
    if(kind==='ezus'){
      show('Zapytanie do eZUS — symulacja',`<label class="field-label" for="demo-question-topic">Czego dotyczy sprawa?</label><select id="demo-question-topic"><option value="maternity">Urlopy i zasiłek macierzyński</option><option value="insurance">Ubezpieczenie chorobowe</option><option value="debt">Zadłużenie w składkach</option><option value="care">Opiekuńczy</option><option value="other">Inna sprawa</option></select><label class="field-label" for="demo-question">O co chcesz zapytać?</label><textarea id="demo-question" class="calc-textarea" maxlength="3000" placeholder="Np. które dokumenty potwierdzą moje uprawnienie?"></textarea><button class="primary" id="demo-question-send">Przygotuj zapytanie i listę dokumentów</button><a class="secondary" href="https://www.zus.pl/ezus/logowanie?jezyk=pl" target="_blank" rel="noopener noreferrer">Otwórz portal eZUS</a>`);
      document.querySelector('#demo-question-send').onclick=async()=>{try{const question=document.querySelector('#demo-question').value.trim();if(!question){notify('Wpisz treść zapytania.');return;}const data=await simulate('ezus',{topic:document.querySelector('#demo-question-topic').value}),body=`<h3>Treść zapytania</h3><p>${esc(question)}</p><h3>Przygotuj do tej sprawy</h3><ul>${data.checklist.map(item=>'<li>'+esc(item)+'</li>').join('')}</ul>`;show('Zapytanie — przygotowanie sprawy',`<span class="simulation-label">Symulacja</span>${body}<button class="primary" id="demo-question-download">Pobierz szkic zapytania</button><a class="secondary" href="${data.portalUrl}" target="_blank" rel="noopener noreferrer">Przejdź do eZUS</a>`);document.querySelector('#demo-question-download').onclick=()=>calcDownload('szkic-zapytania-ezus.html',calcDocumentPage('Szkic zapytania do ZUS',body,{simulation:true}));}catch(e){error(e);}};
    }
    if(kind==='application')openApplication();
    if(kind==='usc')openUsc();
  }catch(e){error(e);}}
  function openApplication(){
    const result=getResult();if(!result){notify('Najpierw oblicz scenariusz, aby podstawić właściwe okresy do wniosku.');return;}
    show('Projekt wniosku — symulacja',`${notice}<form id="calc-document-form" class="calc-document-form"><label class="field-label">Rodzaj wniosku<select name="kind"><option value="parental">Urlop rodzicielski</option><option value="maternity">Urlop macierzyński / na warunkach</option><option value="supplement">Uzupełniający macierzyński</option><option value="paternity">Urlop ojcowski</option><option value="work">Łączenie rodzicielskiego z pracą</option><option value="benefit">Dane do wniosku ZUS ZAM / właściwego świadczenia</option><option value="childcare">Urlop wychowawczy / obniżenie etatu</option></select></label><label class="field-label">Rodzic / opiekun<select name="parent"><option value="0">${calcParentLabel(result.input,0)}</option><option value="1">${calcParentLabel(result.input,1)}</option></select></label><label class="field-label">Imię i nazwisko wnioskującego<input name="applicant" maxlength="200" placeholder="Możesz użyć danych przykładowych"></label><label class="field-label">Imię i nazwisko dziecka<input name="child" maxlength="200" value="${esc(getProfile().name||'')}"></label><label class="field-label">Adresat / płatnik<input name="recipient" maxlength="300" placeholder="Nazwa pracodawcy albo jednostka ZUS"></label><div class="calc-fields"><label class="field-label">Od<input type="date" name="start"></label><label class="field-label">Do<input type="date" name="end"></label></div><label class="field-label">Dodatkowe oświadczenia i szczegóły<textarea class="calc-textarea" name="additional" maxlength="5000" placeholder="Historia wykorzystanych części, drugi rodzic, wymiar pracy, dokumenty szczególne…"></textarea></label><button class="primary" type="submit">Pokaż wypełniony projekt</button></form>`);
    const form=document.querySelector('#calc-document-form');
    const setPeriod=()=>{const parent=Number(form.elements.parent.value),kind=form.elements.kind.value,part=result.periods.find(p=>p.parent===parent&&(kind==='parental'?p.id.startsWith('parental'):kind==='paternity'?p.id.startsWith('paternity'):kind==='supplement'?p.id==='supplement':kind==='maternity'?p.id.startsWith('maternity'):true));if(part){form.elements.start.value=part.start;form.elements.end.value=part.end;}};form.elements.kind.onchange=setPeriod;form.elements.parent.onchange=setPeriod;setPeriod();
    for(const name of ['applicant','child'])form.elements[name].oninput=()=>{form.elements[name].value=cleanName(form.elements[name].value);};
    form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form)),parent=Number(values.parent),doc=result.documents.find(d=>d.parent===parent),heading=form.elements.kind.selectedOptions[0].textContent;
      if(values.start&&values.end&&values.start>values.end){notify('Koniec okresu nie może poprzedzać początku.');return;}
      const body=`<p>Data sporządzenia: ${calendarDate(todayString())}</p><p>Wnioskujący: ${esc(values.applicant||'[do uzupełnienia]')}<br>Adresat: ${esc(values.recipient||doc?.recipient||'[do uzupełnienia]')}</p><h2>${esc(heading)}</h2><p>Dziecko: ${esc(values.child||'[do uzupełnienia]')}; data zdarzenia: ${calendarDate(result.input.eventDate)}.</p><p>Wnioskuję o okres od ${values.start?calendarDate(values.start):'[do uzupełnienia]'} do ${values.end?calendarDate(values.end):'[do uzupełnienia]'}.</p><p>${esc(values.additional||'Oświadczenia dotyczące drugiego rodzica, wcześniejszego wykorzystania oraz pracy wymagają sprawdzenia i uzupełnienia przed rzeczywistym złożeniem.')}</p><h3>Załączniki i informacje do sprawdzenia</h3><ul>${(doc?.items||[]).map(item=>`<li>${esc(item)}</li>`).join('')}</ul><p>Wniosek pracowniczy: dane i podpis wymagają potwierdzenia. Dla świadczenia ZUS użyj aktualnego oryginalnego formularza — ten podgląd jest zestawieniem danych, a nie jego zamiennikiem.</p>${(doc?.forms||[]).map(f=>`<p><a href="${f.url}">Oryginalny ${f.code} na stronie ZUS</a></p>`).join('')}<p>Podpis: _______________________</p>`;
      show('Projekt wniosku — symulacja',notice+body+'<div class="calc-action-row"><button class="primary" id="calc-doc-download">Pobierz projekt / drukuj do PDF</button><button class="secondary" id="calc-doc-send">Przećwicz wysłanie — symulacja</button></div><p id="calc-demo-receipt" role="status"></p>');
      document.querySelector('#calc-doc-download').onclick=()=>calcDownload('DEMO-wniosek.html',calcDocumentPage(heading,body,{simulation:true}));
      document.querySelector('#calc-doc-send').onclick=async()=>{try{const receipt=await simulate('application');document.querySelector('#calc-demo-receipt').textContent=receipt.reference+' · '+receipt.message;}catch(e){error(e);}};
    };
  }
  function openUsc(){
    show('Odpis aktu urodzenia — symulacja',`<form id="calc-usc-form"><label class="field-label">Rodzaj odpisu<select name="type"><option value="short">Odpis skrócony aktu urodzenia</option><option value="full">Odpis zupełny aktu urodzenia</option></select></label><label class="field-label">Imię i nazwisko dziecka<input name="child" maxlength="200" value="${esc(getProfile()?.name||'')}"></label><label class="field-label">Data urodzenia dziecka<input name="birthDate" type="date" max="${todayString()}" value="${getInput().childBirthDate||''}"></label><label class="field-label">Cel uzyskania<input name="purpose" maxlength="500" placeholder="Np. przygotowanie dokumentów"></label><button class="primary" type="submit">Pokaż przykładowy odpis</button></form><a class="secondary" href="https://www.gov.pl/web/gov/uzyskaj-odpis-aktu-stanu-cywilnego-urodzenia-malzenstwa-zgonu" target="_blank" rel="noopener noreferrer">Oficjalna usługa uzyskania odpisu</a>`);
    document.querySelector('#calc-usc-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.currentTarget)),receipt=await simulate('usc',{childName:data.child,childBirthDate:data.birthDate,extractType:data.type}),x=receipt.extract,body=`<h3>${esc(x.type)}</h3><dl class="case-facts"><div><dt>Dziecko</dt><dd>${esc(x.childName)}</dd></div><div><dt>Data urodzenia</dt><dd>${calendarDate(x.birthDate)}</dd></div><div><dt>Miejsce urodzenia — przykład</dt><dd>${esc(x.birthPlace)}</dd></div><div><dt>Data sporządzenia</dt><dd>${calendarDate(x.issuedAt)}</dd></div></dl>${data.purpose?'<p>Cel: '+esc(data.purpose)+'</p>':''}`;show('Odpis aktu urodzenia — symulacja',body+'<button class="primary" id="calc-usc-use">Użyj daty urodzenia w kalkulatorze</button><button class="secondary" id="calc-usc-download">Pobierz odpis — symulacja</button>');document.querySelector('#calc-usc-download').onclick=()=>calcDownload('przykladowy-odpis.html',calcDocumentPage(x.type,body,{simulation:true}));document.querySelector('#calc-usc-use').onclick=()=>{const fields=[{field:'childBirthDate',value:x.birthDate}];if(getInput().familyType==='birth')fields.push({field:'eventDate',value:x.birthDate});onImport({importFields:fields,parent:0,title:0,demo:true,dateKind:'actual'});document.querySelector('#sheet').close();};}catch(errorValue){error(errorValue);}};
  }
  return {open,openApplication};
}
